const staticData = $getWorkflowStaticData('global');
staticData.existingHaystackFiles = [];

return $input.all()
  .filter((item) => item.json.mimeType !== 'application/vnd.google-apps.folder')
  .map((item) => {
    const f = item.json;
    const owner = (f.owners && f.owners[0]) || {};
    const contentHash = f.md5Checksum || f.headRevisionId || f.modifiedTime;
    return {
      json: {
        source_id: f.id,
        name: f.name,
        mimeType: f.mimeType,
        source_url: f.webViewLink,
        owner_email: owner.emailAddress || '',
        last_modified_by: (f.lastModifyingUser && f.lastModifyingUser.emailAddress) || '',
        drive_modified_time: f.modifiedTime,
        content_hash: contentHash,
      },
    };
  });

const staticData = $getWorkflowStaticData('global');
const items = $input.all();
staticData.currentExistingFile = { file_id: items[0].json.file_id, name: items[0].json.name };
return items;

const staticData = $getWorkflowStaticData('global');
staticData.existingHaystackFiles = staticData.existingHaystackFiles || [];

const items = $input.all();
const original = staticData.currentExistingFile;

for (const item of items) {
  const meta = item.json || {};
  if (meta.source_system === 'google_drive') {
    staticData.existingHaystackFiles.push({
      haystack_file_id: original.file_id,
      name: original.name,
      source_id: meta.source_id || null,
      // Stored with a _text suffix - see the metadata typing sticky note below.
      content_hash: meta.content_hash_text || null,
    });
  }
}

return items;

const staticData = $getWorkflowStaticData('global');
const existing = staticData.existingHaystackFiles || [];
const driveFiles = $('Normalize Drive Files').all().map((i) => i.json);

const existingBySourceId = new Map(existing.map((f) => [f.source_id, f]));
const driveBySourceId = new Map(driveFiles.map((f) => [f.source_id, f]));

const results = [];
const now = $now.toISO();

for (const drive of driveFiles) {
  const match = existingBySourceId.get(drive.source_id);

  if (!match) {
    results.push({ json: { action: 'upload', ...drive, synced_at: now } });
    continue;
  }

  if (match.name !== drive.name) {
    // Overwrite mode matches by file name, so a rename can't be applied in place -
    // recreate it under the new name instead.
    results.push({ json: { action: 'delete', haystack_file_id: match.haystack_file_id, name: match.name } });
    results.push({ json: { action: 'upload', ...drive, synced_at: now } });
    continue;
  }

  if (match.content_hash !== drive.content_hash) {
    results.push({ json: { action: 'update', haystack_file_id: match.haystack_file_id, ...drive, synced_at: now } });
    continue;
  }

  results.push({ json: { action: 'unchanged', ...drive } });
}

for (const existingFile of existing) {
  if (!driveBySourceId.has(existingFile.source_id)) {
    results.push({ json: { action: 'delete', haystack_file_id: existingFile.haystack_file_id, name: existingFile.name } });
  }
}

return results;

// $input.all() is only used to confirm all upload/update/delete branches finished (Merge
// Results is a barrier) - its item content itself isn't usable, since the Haystack Enterprise
// node's own API response overwrites json and drops the 'action' tag Diff set. The definitive
// classification instead comes straight from the Diff node's output.
$input.all();

const details = $('Diff Drive Vs Haystack').all().map((i) => i.json);
const counts = { uploaded: 0, updated: 0, deleted: 0, unchanged: 0 };

for (const item of details) {
  const action = item.action;
  if (action === 'upload') counts.uploaded++;
  else if (action === 'update') counts.updated++;
  else if (action === 'delete') counts.deleted++;
  else counts.unchanged++;
}

const staticData = $getWorkflowStaticData('global');
staticData.indexPollAttempts = 0;

return [{ json: { counts, details } }];

const staticData = $getWorkflowStaticData('global');
staticData.indexPollAttempts = (staticData.indexPollAttempts || 0) + 1;

const indexes = $input.all().map((i) => i.json);

// Only indexes we actually want deployed can ever finish indexing; an index whose
// desired_status is e.g. DELETED or PAUSED may sit with a stale/irrelevant status.
const deployedIndexes = indexes.filter((idx) => idx.desired_status === 'DEPLOYED');
const notReady = deployedIndexes.filter((idx) => (idx.status?.pending_file_count ?? 0) > 0);

const indexStatuses = indexes.map((idx) => ({
  name: idx.name,
  desired_status: idx.desired_status,
  indexed_no_documents_file_count: idx.status?.indexed_no_documents_file_count ?? null,
  indexed_file_count: idx.status?.indexed_file_count ?? null,
  pending_file_count: idx.status?.pending_file_count ?? null,
  failed_file_count: idx.status?.failed_file_count ?? null,
  total_file_count: idx.status?.total_file_count ?? null,
}));

return [{
  json: {
    allReady: notReady.length === 0,
    attempts: staticData.indexPollAttempts,
    timedOut: staticData.indexPollAttempts >= 40,
    notReadyIndexes: notReady.map((idx) => idx.name),
    indexStatuses,
  },
}];

const summary = $('Build Change Summary').first().json;
const indexStatus = $input.first().json;

const lines = [
  'Google Drive -> Haystack Enterprise sync report',
  `Uploaded: ${summary.counts.uploaded}`,
  `Updated: ${summary.counts.updated}`,
  `Deleted: ${summary.counts.deleted}`,
  `Unchanged: ${summary.counts.unchanged}`,
  '',
  indexStatus.allReady
    ? `Indexes finished reconciling after ${indexStatus.attempts} check(s).`
    : `Timed out waiting for indexes after ${indexStatus.attempts} checks. Still not ready: ${indexStatus.notReadyIndexes.join(', ')}`,
  '',
  'Index status:',
  ...indexStatus.indexStatuses.map((idx) =>
    `- ${idx.name} (desired: ${idx.desired_status}): ${idx.indexed_file_count} indexed, ${idx.pending_file_count} pending, ${idx.failed_file_count} failed, ${idx.indexed_no_documents_file_count} indexed w/o documents, ${idx.total_file_count} total`,
  ),
];

return [{
  json: {
    summary: summary.counts,
    details: summary.details,
    indexStatus,
    reportText: lines.join('\n'),
  },
}];
